// Convert dodge/attack stamina into mana only after holding the casting position.
const STAMINA_TRANSMUTE_SIGNATURE=['余力の錬成',0,10,'SPを最大40消費し、発動地点から24以内に0.6秒留まると、消費SPの75%をMPへ変換（最大30、MP上限100）。途中で離れる・壁に遮られる・死亡・地域移動で中断し、消費SPは戻らない。SP0なら回復なし。敵への攻撃はなく、属性・範囲・威力補正は変換量に影響しない。MP満タンでもSPを消費。再発動で前の錬成を置き換える。','M10 10H22V23H10ZM30 29H42V42H30ZM11 35H23L18 30M23 35L18 40M41 17H29L34 12M29 17L34 22'];
SIGNATURE_SKILLS.push(STAMINA_TRANSMUTE_SIGNATURE);Object.assign(GEM.crafted_5_6,{name:STAMINA_TRANSMUTE_SIGNATURE[0],cost:0,cool:10,desc:STAMINA_TRANSMUTE_SIGNATURE[3],ability:null,signature:102,tags:['spell']});
SIGNATURE_AUDIO.push(['staminatransmute',480,.3]);SKILL_AUDIO_FAMILIES.airy.add('staminatransmute');
function staminaTransmuteValid(s){return s.owner===p&&s.world===dungeon&&!s.finished&&!dead&&p?.hp>0&&dist(p,s.origin)<=24&&lineClear(p,s.origin);}
const staminaTransmuteCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{const result=staminaTransmuteCastBase(build,...args);if(GEM[build.type]?.signature!==102)return result;const s=signatureSpells.at(-1);if(s?.mode!==102)return result;ensureClassResources();signatureSpells=signatureSpells.filter(v=>v.mode!==102||v===s);Object.assign(s,{owner:p,world:dungeon,finished:false,target:null,spent:Math.min(40,p.sp),x:p.x,y:p.y,origin:{x:p.x,y:p.y}});p.sp-=s.spent;if(s.spent>0)classRest=Math.max(classRest,.6);return result;};
const staminaTransmuteStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==102)return staminaTransmuteStepBase(s,dt);if(!staminaTransmuteValid(s)){s.finished=true;return false;}if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time+=dt;if(s.time+1e-8<.6)return true;s.finished=true;p.mp=Math.min(100,p.mp+s.spent*.75);burst(s.x,s.y,45,'#8bdaf0');playSignatureAudio(102,true,s.x,s.y);return false;};
const staminaTransmutePaintBase=paintSignatureSpells;paintSignatureSpells=()=>{staminaTransmutePaintBase();const renderList=signatureRenderList(102,102);if(!renderList.length)return;for(const s of renderList){if(s.mode!==102||!staminaTransmuteValid(s)||!visibleAt(s.x,s.y))continue;groundRing(s.x,s.y,24,'#e1bc72',2);groundRing(s.x,s.y,8+16*Math.min(1,s.time/.6),'#8bdaf0',3);paintLinkLine({x:s.x-18,y:s.y},{x:s.x+18,y:s.y},'#8bdaf0',2);}};
const staminaTransmuteStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===102?{label:'錬成 · MP +'+Math.round(s.spent*.75),value:Math.min(1,s.time/.6),waiting:true}:staminaTransmuteStatusBase(s);
